-- Semilla SINTÉTICA para pruebas aisladas de Rafa. NO ejecutar en producción.
-- Identificadores fijos para que las pruebas puedan referirse a ellos.
-- Semana de referencia de las pruebas: lunes 2026-10-12 a domingo 2026-10-18.

-- Usuarios: admin, contador, usuario asignado a P1, arquitecto, usuario sin proyectos.
-- handle_new_user creó perfiles y rol 'usuario'; se ajustan los roles.
UPDATE public.user_roles SET role = 'admin' WHERE user_id = '00000000-0000-0000-0000-0000000000a1';
UPDATE public.user_roles SET role = 'contador' WHERE user_id = '00000000-0000-0000-0000-0000000000c1';
UPDATE public.user_roles SET role = 'arquitecto' WHERE user_id = '00000000-0000-0000-0000-0000000000d1';






-- Partidas

-- Flujos legacy (partida no Project): 12 rentas mensuales.
SELECT 'b1000000-0000-0000-0000-00000000000b', 'e1000000-0000-0000-0000-000000000001',
       (date '2026-01-05' + (n || ' month')::interval)::date, 10000, 'egreso', 'Renta mes ' || (n + 1)
FROM generate_series(0, 11) n;

-- Proyecto P1 sobre Obra Norte y su programación propia de Cimentación.

-- Asientos: se crean en borrador, se capturan renglones y luego se aplican
-- (así dispara el trigger de IVA igual que en la aplicación).
UPDATE public.asientos_contables SET estado = 'aplicado'
WHERE id IN ('a5000000-0000-0000-0000-000000000001', 'a5000000-0000-0000-0000-000000000002', 'a5000000-0000-0000-0000-000000000004', 'a5000000-0000-0000-0000-000000000005');

